        String zsoId,
        long projectId,
        long apId,
        String moduleName,
        String issueTitle,
        String issueDescription,
        String crashLink
) {
    try {
        JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
        if (jiraAuth == null) {
            LOGGER.log(Level.INFO, "Jira Auth is null");
            return false;
        }

        JSONObject configuration = IntegrationHandler.getIntegrationDetailsByService(
                AppticsConstants.JIRA,
                moduleName,
                "unique",
                apId
        );
        if (configuration == null) {
            LOGGER.log(Level.INFO, "Jira Config is null");
            return false;
        }

        LOGGER.log(Level.INFO, "Jira Config {0}", configuration.toString());

        String jiraCloudId = configuration.getString("cloud_id");
        String jiraProjectId = configuration.getString("project_id");
        String jiraIssueTypeId = configuration.getString("issue_type_id");

        if (CommonUtil.isEmpty(jiraProjectId, jiraIssueTypeId)) {
            return false;
        }

        JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
            if (CommonUtil.isEmpty(token, jiraCloudId)) {
                return null;
            }

            String addIssueUrl = JIRA_BASE_URL
                    + "/ex/jira/" + jiraCloudId
                    + "/rest/api/3/issue";

            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + token);

            String createIssueResponse = new HttpURLConnectionInvoker(true)
                    .invokePostHttpURLConnWithRequestBody(
                            addIssueUrl,
                            headers,
                            null,
                            buildRequestBodyToCreateIssue(jiraProjectId, jiraIssueTypeId, issueTitle, issueDescription, crashLink)
                    );
            return new JSONObject(createIssueResponse);
        });

        if (jiraResponse.has("id")) {
            return true;

