								zsoid,
								appID,
								bundleId,
								bugTitle,
								message,
								crashurl
						);

					}
				} else {
					sendToMsTeams(module, "all", bundleId, displayName, crashurl, crashEntity);
				}

				try{
					String content = getChatcontent(displayName, crashurl, 1,crashEntity);

					String cliqContent = content + "[Crash Details]("+crashurl+")";
					cliqIntegration(module, cliqsubtype, bundleId, cliqContent);

					String slackContent = content + "<"+crashurl+"|Crash Details>";
					Integrations.SLACK.sendMessage(module, cliqsubtype, bundleId, slackContent);
				}
				catch(Exception e){
					LOGGER.log(Level.INFO, "Exception while send message to cliq {0}", new Object[] {e});
				}
			}
			catch(Exception e){

				LOGGER.log(Level.INFO, "Exception while sending Crash/Non Fatal exception mail {0}", new Object[] {e});
			}

		}

