	public boolean sendToAsana(String zsoId, long projectId, long apId, String taskTitle, String taskDescription, String crashLink) {
		try {
			String accessToken = getAccessToken(zsoId, projectId);
			if (accessToken == null) {
				LOGGER.log(Level.INFO, "Asana access token not found for project {0}", projectId);
				return false;
			}

			JSONObject asanaConfig = getConfiguration(apId);
			if (asanaConfig == null) {
				LOGGER.log(Level.INFO, "Asana config not found for apId {0}", apId);
				return false;
			}

			JSONObject configuration = asanaConfig.optJSONObject("Configuration");
			if (configuration == null) {
				LOGGER.log(Level.INFO, "Asana configuration object is null for apId {0}", apId);
				return false;
			}

			String workspaceGid = configuration.optString("workspaceGid", null);
			String projectGid = configuration.optString("projectGid", null);

			LOGGER.log(Level.INFO, "ASANA workspaceGid {0}, projectGid {1}", new Object[] { workspaceGid, projectGid });

			if (CommonUtil.isEmpty(workspaceGid, projectGid)) {
				LOGGER.log(Level.INFO, "Asana workspaceGid/projectGid missing for apId {0}", apId);
				return false;
			}

			String taskDesc = crashLink + "\n\n" + taskDescription; // no i18N

			JSONObject result = addAsanaTask(zsoId, projectId, workspaceGid, projectGid, taskTitle, taskDesc, null);
			LOGGER.log(Level.INFO, "Asana task creation result: {0}", result);
			return result != null && result.has("data");

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while sending crash to Asana", e);
		}
		return false;
	}

