private Boolean addBugInDB(Long appID, Long uniqueid, Long versionid, Long bugid, String projectid, String portalid, String assignee, String severity,  String bugUrl){
	String tablename = CRASHUPDATESTAB+appID;

	Row r = new Row(tablename);

	r.set("UniqueMessageID", uniqueid);
	r.set("VersionID", versionid);
	r.set("PortalID", portalid);
	r.set("ProjectID", projectid);
	r.set("Severiority", severity);
	r.set("BugID", ""+bugid);
	r.set("BugURL", bugUrl);
	r.set("AssignedPerson", assignee);
	r.set("Status", 0);
	r.set("Date", System.currentTimeMillis());
	r.set("UpdatedDate", System.currentTimeMillis());

	try 
	{
		DBHandler.insertRow(r, tablename, "CID");
	}
	catch (DataAccessException e) 
	{
		LOGGER.log(Level.SEVERE,"Exception while inserting bug in crashupdates table ", e);
		return false;
	}

	return true;
}

